import { useCartStore } from '../store/cart'

export default function Cart() {
  const { items, total } = useCartStore()
  return (
    <div>
      <h1>Shopping Cart</h1>
      {items.length === 0 ? <p>Cart is empty</p> : (
        <>
          <ul>
            {items.map((item, i) => (
              <li key={i}>{item.name} - ${item.price}</li>
            ))}
          </ul>
          <h3>Total: ${total}</h3>
        </>
      )}
    </div>
  )
}

